-- Blessed Hammer (420092) - AreaTrigger 29807 : spirale d'Archimede en spline (remplace l'orbite vide qui faisait crasher)
-- 3 tours en 5 s, rayon de 2 a 10, 1.5 au-dessus du sol. Offsets relatifs, tournes selon l'orientation du lanceur.
DELETE FROM `areatrigger_create_properties_orbit` WHERE `AreaTriggerCreatePropertiesId`=29807 AND `IsCustom`=0;

-- Spirale entiere parcourue en 5 s (duree de l'AreaTrigger)
UPDATE `areatrigger_create_properties` SET `Speed`=5, `SpeedIsTime`=1 WHERE `Id`=29807 AND `IsCustom`=0;

DELETE FROM `areatrigger_create_properties_spline_point` WHERE `AreaTriggerCreatePropertiesId`=29807 AND `IsCustom`=0;
